/buyers-guide/paddles/werner-sherpa-carbon","batch":"photos-1101"}]},{"category":"paddle","brand":"Werner","model":"Sherpa Carbon","variant":"1 piece, straight shaft","size":null,"images":[{"url":"https://cdn.shopify.com/s/files/1/0552/0719/8768/files/elufywpswoa3htlvipaq.jpg?v=1789687961","page_url":"https://store.noc.com/products/werner-sherpa-carbon","batch":"photos-1101"},{"url":"https://playak.com/media/reviews/photos/original/6d/d0/62/3003_SherpaCarbon_1260791030.jpg","page_url":"https://playak.com/buyers-guide/paddles/werner-sherpa-carbon","batch":"photos-1101"}]},{"category":"paddle","brand":"Werner","model":"Sho-Gun","variant":"1 piece, bent shaft","size":null,"images":[{"url":"https://cdn.shopify.com/s/files/1/0552/0719/8768/files/WernerShoGunCarbonBentShaftPaddleBlade.jpg?v=1726515154","page_url":"https://store.noc.com/products/werner-sho-gun-bent","batch":"photos-1101"},{"url":"https://playak.com/media/reviews/photos/original/48/10/f4/1475_SNAG2052_1260201979.jpg","page_url":"https://playak.com/buyers-guide/paddles/werner-sho-gun","batch":"photos-1101"}]},{"category":"paddle","brand":"Werner","model":"Sho-Gun","variant":"1 piece, straight shaft","size":null,"images":[{"url":"https://cdn.shopify.com/s/files/1/0552/0719/8768/files/Werner_Sho_Gun_Carbon_Straight_Shaft_Kayak_Paddle.webp?v=1738786323","page_url":"https://store.noc.com/products/werner-sho-gun-straight","batch":"photos-1101"},{"url":"https://playak.com/media/reviews/photos/original/48/10/f4/1475_SNAG2052_1260201979.jpg","page_url":"https://playak.com/buyers-guide/paddles/werner-sho-gun","batch":"photos-1101"}]},{"category":"paddle","brand":"Werner","model":"Side Kick","variant":"1 piece, bent shaft","size":null,"images":[{"url":"https://playak.com/media/reviews/photos/original/94/c5/ea/3029_SNAG1053_1291329338.jpg","page_url":"https://playak.com/buyers-guide/paddles/werner-side-kick","batch":"photos-1101"}]},{"category":"paddle","brand":"Werner","model":"Side Kick","variant":"1 piece, straight shaft","size":null,"images":[{"url":"https://playak.com/media/reviews/photos/original/94/c5/ea/3029_SNAG1053_1291329338.jpg","page_url":"https://playak.com/buyers-guide/paddles/werner-side-kick","batch":"photos-1101"}]},{"category":"paddle","brand":"Werner","model":"Stikine","variant":"1 piece, bent shaft","size":null,"images":[{"url":"https://cdn.shopify.com/s/files/1/0552/0719/8768/products/stikinebentimage.jpg?v=1738704116","page_url":"https://store.noc.com/products/werner-stikine-bent","batch":"photos-1101"},{"url":"https://playak.com/media/reviews/photos/original/db/36/35/3000_StikineS_1260785866.jpg","page_url":"https://playak.com/buyers-guide/paddles/werner-stikine","batch":"photos-1101"}]},{"category":"paddle","brand":"Werner","model":"Strike","variant":"1 piece, bent shaft","size":null,"images":[{"url":"https://cdn.shopify.com/s/files/1/0552/0719/8768/files/WernerStrikeBentShaftKayakPaddleGalaxy.webp?v=1738699930","page_url":"https://store.noc.com/products/werner-strike-bent","batch":"photos-1101"}]},{"category":"paddle","brand":"Werner","model":"Strike","variant":"1 piece, straight shaft","size":null,"images":[{"url":"https://cdn.shopify.com/s/files/1/0552/0719/8768/files/c5t0rrcifovvodsv1mlh.jpg?v=1738699931","page_url":"https://store.noc.com/products/werner-strike-straight","batch":"photos-1101"}]},{"category":"paddle","brand":"Werner","model":"Strike","variant":"4 piece, straight shaft","size":null,"images":[{"url":"https://cdn.shopify.com/s/files/1/0552/0719/8768/files/c5t0rrcifovvodsv1mlh.jpg?v=1738699931","page_url":"https://store.noc.com/products/werner-strike-straight","batch":"photos-1101"}]},{"category":"paddle","brand":"Werner","model":"Surge","variant":"1 piece, bent shaft","size":null,"images":[{"url":"https://cdn.shopify.com/s/files/1/0552/0719/8768/files/WernerSurgeBentShaftKayakPaddle.webp?v=1738699892","page_url":"https://store.noc.com/products/werner-surge-bent","batch":"photos-1101"}]},{"category":"paddle","brand":"Werner","model":"Surge","variant":"1 piece, straight shaft","size":null,"images":[{"url":"https://cdn.shopify.com/s/files/1/0552/0719/8768/products/Surge-Blaze-Blade-straight_01_585x_414186e8-514b-4eb6-ae4d-c6cc92140c6c.jpg?v=1738700607","page_url":"https://store.noc.com/products/werner-surge-straight","batch":"photos-1101"}]},{"category":"paddle","brand":"Werner","model":"Surge","variant":"4 piece, straight shaft","size":null,"images":[{"url":"https://cdn.shopify.com/s/files/1/0552/0719/8768/products/Surge_Blaze_4pc_Paddle_03_585x_acfb3768-20ec-45d3-ac36-5ef105fb099f.jpg?v=1738700827","page_url":"https://store.noc.com/products/werner-surge-4pc","batch":"photos-1101"}]},{"category":"paddle","brand":"Werner","model":"Twist","variant":"1 piece, bent shaft","size":null,"images":[{"url":"https://playak.com/media/reviews/photos/original/82/6d/77/3031_Twist_1260861547.jpg","page_url":"https://playak.com/buyers-guide/paddles/werner-twist","batch":"photos-1101"}]},{"category":"paddle","brand":"Werner","model":"Twist","variant":"1 piece, straight shaft","size":null,"images":[{"url":"https://playak.com/media/reviews/photos/original/82/6d/77/3031_Twist_1260861547.jpg","page_url":"https://playak.com/buyers-guide/paddles/werner-twist","batch":"photos-1101"}]},{"category":"paddle","brand":"Werner","model":"Twist","variant":"4 piece, straight shaft","size":null,"images":[{"url":"https://playak.com/media/reviews/photos/original/82/6d/77/3031_Twist_1260861547.jpg","page_url":"https://playak.com/buyers-guide/paddles/werner-twist","batch":"photos-1101"}]}]$seed$::jsonb) AS s(
        category material_category, brand text, model text, variant text, size text,
        images jsonb
    )
), target AS (
    SELECT m.id AS material_id, s.brand, s.images
    FROM seed s
    JOIN materials m ON m.category = s.category
        AND lower(btrim(m.brand)) = lower(btrim(s.brand))
        AND lower(btrim(m.model)) = lower(btrim(s.model))
        AND lower(btrim(COALESCE(m.variant, ''))) = lower(btrim(COALESCE(s.variant, '')))
        AND lower(btrim(COALESCE(m.size, ''))) = lower(btrim(COALESCE(s.size, '')))
        AND m.created_by = 'system-catalogue'
    WHERE NOT EXISTS (
        SELECT 1 FROM materials o
        JOIN material_images oi ON oi.material_id = o.id
        WHERE o.category = m.category
          AND lower(btrim(o.brand)) = lower(btrim(m.brand))
          AND lower(btrim(o.model)) = lower(btrim(m.model))
          AND lower(btrim(COALESCE(o.variant, ''))) = lower(btrim(COALESCE(m.variant, '')))
    )
)
INSERT INTO material_images (material_id, source_url, host, page_url, credit)
SELECT t.material_id, i->>'url', lower(substring(i->>'url' from '^https://([^/?#:@]+)')),
       i->>'page_url', t.brand
FROM target t
CROSS JOIN LATERAL jsonb_array_elements(t.images) AS i
ON CONFLICT (material_id, source_url) DO NOTHING;
